// Characterization tests: pin CURRENT total/discount behaviour so refactors that change it fail.
// Cases marked "SUSPECT" document behaviour that may be a bug; update deliberately if fixed.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 33.33, C: 0.1, D: 101, E: 100, F: 50 }

async function withApp(fn) {
  const server = createServer(createApp({ pricing: { priceOf: async (sku) => prices[sku] } }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function total(base, items) {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  const order = await res.json()
  const fetched = await (await fetch(`${base}/orders/${order.id}`)).json()
  assert.equal(fetched.total, order.total)
  return order.total
}

const cases = [
  ['small order, no discount', [{ sku: 'A', qty: 5 }], 50],
  ['exactly 100 gets no discount', [{ sku: 'E', qty: 1 }], 100],
  ['just over 100 gets 10% off (101 -> 90.9, floored)', [{ sku: 'D', qty: 1 }], 90],
  ['large order: 10 x 50 = 500 -> 450', [{ sku: 'F', qty: 10 }], 450],
  ['multiple items summed before discount: 60+50=110 -> 99', [{ sku: 'A', qty: 6 }, { sku: 'F', qty: 1 }], 99],
  // SUSPECT: total is floored to whole euros, dropping cents (also 3 x 33.33 = 99.99 -> 99)
  ['SUSPECT: cents truncated without discount', [{ sku: 'B', qty: 3 }], 99],
  // SUSPECT: 133.32 * 0.9 = 119.988 -> 119, not 119.99 / 120
  ['SUSPECT: cents truncated with discount', [{ sku: 'B', qty: 4 }], 119],
  // SUSPECT: floating point, 0.1 * 1010 = 101 may land just under/over the threshold
  ['SUSPECT: float accumulation near threshold', [{ sku: 'C', qty: 1000 }], 100],
]

for (const [name, items, expected] of cases) {
  test(name, () => withApp(async (base) => assert.equal(await total(base, items), expected)))
}

test('empty items rejected', () => withApp(async (base) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items: [] }) })
  assert.equal(res.status, 400)
}))
EOF
